select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Botnation AI' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme française sans code pour créer des chatbots et agents IA pour sites et messageries, formés sur votre documentation et à l''image de votre marque.',
  'French no-code platform to build AI chatbots and agents for websites and messaging, trained on your documentation and branded for your company.');
