select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Botnation AI', 'Brand24 AI Brand Assistant', 'Claude (Anthropic)', 'IBM watsonx Orchestrate', 'Deepgram Voice Agent API', 'Telnyx AI Agents', 'Workday AI Agents', 'ServiceNow AI Agents') order by e.name;
